//! Comment JSON persistence format.
//!
//! The canonical file shape is a wrapper object:
//!
//! ```json
//! {
//!   "version": 1,
//!   "comments": []
//! }
//! ```
//!
//! The wrapper gives persisted user data an explicit migration point. A bare
//! JSON array is still accepted as version 1 input so older planning examples
//! can be read by the future store implementation. Timestamps are stored here
//! but generated by Rust application/domain code before conversion.

use std::str::FromStr;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::domain::{
    comment::{
        BlockIndex, BlockType, CharRange, Comment, CommentAnchor, CommentBody, CommentDomainError,
        CommentId, CommentScope, CommentStatus, ScopedComments, ScopedCommentsError, TextHash,
        TextSnippet,
    },
    spec::SpecFileKey,
};

const COMMENT_JSON_VERSION: u32 = 1;

pub fn serialize_comments(comments: &ScopedComments) -> Result<String, CommentJsonError> {
    let document = CommentJsonDocument::from_domain(comments.comments());

    serde_json::to_string_pretty(&document).map_err(CommentJsonError::Serialize)
}

pub fn deserialize_comments(
    scope: CommentScope,
    contents: &str,
) -> Result<ScopedComments, CommentJsonError> {
    let document = CommentJsonDocument::parse(contents)?;

    document.into_domain(scope)
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
struct CommentJsonDocument {
    #[serde(default = "default_comment_json_version")]
    version: u32,
    #[serde(default)]
    comments: Vec<CommentRecordDto>,
}

impl CommentJsonDocument {
    fn from_domain(comments: &[Comment]) -> Self {
        let comments = comments
            .iter()
            .map(CommentRecordDto::from_domain)
            .collect::<Vec<_>>();

        Self {
            version: COMMENT_JSON_VERSION,
            comments,
        }
    }

    fn parse(contents: &str) -> Result<Self, CommentJsonError> {
        let payload: CommentJsonPayload =
            serde_json::from_str(contents).map_err(CommentJsonError::MalformedJson)?;

        let document = match payload {
            CommentJsonPayload::Document(document) => document,
            CommentJsonPayload::LegacyArray(comments) => Self {
                version: COMMENT_JSON_VERSION,
                comments,
            },
        };

        if document.version != COMMENT_JSON_VERSION {
            return Err(CommentJsonError::UnsupportedVersion {
                version: document.version,
            });
        }

        Ok(document)
    }

    fn into_domain(self, scope: CommentScope) -> Result<ScopedComments, CommentJsonError> {
        let file_key = scope.file_key();
        let comments = self
            .comments
            .into_iter()
            .map(|comment| comment.into_domain(file_key))
            .collect::<Result<Vec<_>, _>>()?;

        ScopedComments::restore(scope, comments).map_err(CommentJsonError::Aggregate)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(untagged)]
enum CommentJsonPayload {
    Document(CommentJsonDocument),
    LegacyArray(Vec<CommentRecordDto>),
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CommentRecordDto {
    id: String,
    anchor: CommentAnchorDto,
    body: String,
    #[serde(default)]
    resolved: bool,
    created_at: DateTime<Utc>,
    updated_at: DateTime<Utc>,
}

impl CommentRecordDto {
    fn from_domain(comment: &Comment) -> Self {
        let anchor = CommentAnchorDto::from_domain(comment.anchor());

        Self {
            id: comment.id().as_str().to_string(),
            anchor,
            body: comment.body().as_str().to_string(),
            resolved: comment.is_resolved(),
            created_at: comment.created_at(),
            updated_at: comment.updated_at(),
        }
    }

    fn into_domain(self, file_key: SpecFileKey) -> Result<Comment, CommentJsonError> {
        let status = if self.resolved {
            CommentStatus::Resolved
        } else {
            CommentStatus::Open
        };

        Comment::restore(
            CommentId::new(self.id).map_err(CommentJsonError::Domain)?,
            self.anchor.into_domain(file_key)?,
            CommentBody::new(self.body).map_err(CommentJsonError::Domain)?,
            status,
            self.created_at,
            self.updated_at,
        )
        .map_err(CommentJsonError::Domain)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CommentAnchorDto {
    block_type: String,
    block_index: usize,
    text_hash: String,
    text_snippet: String,
    char_offset: [usize; 2],
}

impl CommentAnchorDto {
    fn from_domain(anchor: &CommentAnchor) -> Self {
        let char_range = anchor.char_range();

        Self {
            block_type: block_type_to_json(anchor.block_type()).to_string(),
            block_index: anchor.block_index().value(),
            text_hash: anchor.text_hash().as_str().to_string(),
            text_snippet: anchor.text_snippet().as_str().to_string(),
            char_offset: [char_range.start(), char_range.end()],
        }
    }

    fn into_domain(self, file_key: SpecFileKey) -> Result<CommentAnchor, CommentJsonError> {
        Ok(CommentAnchor::new(
            file_key,
            block_type_from_json(&self.block_type)?,
            BlockIndex::new(self.block_index),
            TextHash::new(self.text_hash).map_err(CommentJsonError::Domain)?,
            TextSnippet::new(self.text_snippet).map_err(CommentJsonError::Domain)?,
            CharRange::new(self.char_offset[0], self.char_offset[1])
                .map_err(CommentJsonError::Domain)?,
        ))
    }
}

#[derive(Debug, Error)]
pub enum CommentJsonError {
    #[error("comment JSON is malformed")]
    MalformedJson(serde_json::Error),
    #[error("failed to serialize comment JSON")]
    Serialize(serde_json::Error),
    #[error("unsupported comment JSON version: {version}")]
    UnsupportedVersion { version: u32 },
    #[error("unsupported comment anchor block type: {block_type}")]
    UnsupportedBlockType { block_type: String },
    #[error("comment JSON contains invalid domain data")]
    Domain(CommentDomainError),
    #[error("comment JSON violates scoped comment invariants: {0}")]
    Aggregate(ScopedCommentsError),
}

fn default_comment_json_version() -> u32 {
    COMMENT_JSON_VERSION
}

fn block_type_to_json(block_type: BlockType) -> &'static str {
    match block_type {
        BlockType::Paragraph => "paragraph",
        BlockType::Heading => "heading",
        BlockType::ListItem => "list_item",
        BlockType::CodeBlock => "code_block",
        BlockType::BlockQuote => "block_quote",
        BlockType::Table => "table",
        BlockType::ThematicBreak => "thematic_break",
        BlockType::Html => "html",
        BlockType::Other => "other",
    }
}

fn block_type_from_json(block_type: &str) -> Result<BlockType, CommentJsonError> {
    match block_type {
        "paragraph" => Ok(BlockType::Paragraph),
        "heading" => Ok(BlockType::Heading),
        "list_item" => Ok(BlockType::ListItem),
        "code_block" => Ok(BlockType::CodeBlock),
        "block_quote" => Ok(BlockType::BlockQuote),
        "table" => Ok(BlockType::Table),
        "thematic_break" => Ok(BlockType::ThematicBreak),
        "html" => Ok(BlockType::Html),
        "other" => Ok(BlockType::Other),
        _ => Err(CommentJsonError::UnsupportedBlockType {
            block_type: block_type.to_string(),
        }),
    }
}

impl FromStr for CommentJsonDocument {
    type Err = CommentJsonError;

    fn from_str(contents: &str) -> Result<Self, Self::Err> {
        Self::parse(contents)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::spec::SpecId;

    fn timestamp(second: u32) -> DateTime<Utc> {
        DateTime::parse_from_rfc3339(&format!("2026-05-05T10:00:{second:02}Z"))
            .expect("timestamp should parse")
            .with_timezone(&Utc)
    }

    fn comment(id: &str, file_key: SpecFileKey, block_type: BlockType, resolved: bool) -> Comment {
        let status = if resolved {
            CommentStatus::Resolved
        } else {
            CommentStatus::Open
        };

        Comment::restore(
            CommentId::new(id).expect("comment id should be valid"),
            CommentAnchor::new(
                file_key,
                block_type,
                BlockIndex::new(3),
                TextHash::new("sha256_prefix_8chars").expect("hash should be valid"),
                TextSnippet::new("JWT token").expect("snippet should be valid"),
                CharRange::new(12, 24).expect("range should be valid"),
            ),
            CommentBody::new("Define refresh token expiry").expect("body should be valid"),
            status,
            timestamp(0),
            timestamp(1),
        )
        .expect("comment should be valid")
    }

    fn scope(file_key: SpecFileKey) -> CommentScope {
        CommentScope::new(
            SpecId::new("auth-flow").expect("spec id should be valid"),
            file_key,
        )
    }

    fn deserialize_for_file(
        file_key: SpecFileKey,
        contents: &str,
    ) -> Result<ScopedComments, CommentJsonError> {
        deserialize_comments(scope(file_key), contents)
    }

    #[test]
    fn serialize_comments_uses_versioned_wrapper_and_stable_field_names() {
        let comments = ScopedComments::restore(
            scope(SpecFileKey::Impl),
            vec![comment(
                "cmt_1a2b3c",
                SpecFileKey::Impl,
                BlockType::Paragraph,
                false,
            )],
        )
        .expect("aggregate should restore");
        let json = serialize_comments(&comments).expect("comments should serialize");
        let value: serde_json::Value =
            serde_json::from_str(&json).expect("serialized JSON should parse");

        assert_eq!(serde_json::json!(1), value["version"]);
        assert!(value["comments"].is_array());
        assert_eq!(serde_json::json!("cmt_1a2b3c"), value["comments"][0]["id"]);
        assert!(value["comments"][0]["anchor"].is_object());
        assert_eq!(
            serde_json::json!("Define refresh token expiry"),
            value["comments"][0]["body"]
        );
        assert_eq!(serde_json::json!(false), value["comments"][0]["resolved"]);
        assert_eq!(
            serde_json::json!("2026-05-05T10:00:00Z"),
            value["comments"][0]["createdAt"]
        );
        assert_eq!(
            serde_json::json!("2026-05-05T10:00:01Z"),
            value["comments"][0]["updatedAt"]
        );
    }

    #[test]
    fn deserialize_comments_round_trips_domain_comments() {
        let scope = scope(SpecFileKey::Impl);
        let expected = ScopedComments::restore(
            scope.clone(),
            vec![
                comment("cmt_open", SpecFileKey::Impl, BlockType::Paragraph, false),
                comment(
                    "cmt_resolved",
                    SpecFileKey::Impl,
                    BlockType::CodeBlock,
                    true,
                ),
            ],
        )
        .expect("aggregate should restore");
        let json = serialize_comments(&expected).expect("comments should serialize");

        let actual = deserialize_comments(scope, &json).expect("comments should deserialize");

        assert_eq!(expected, actual);
    }

    #[test]
    fn deserialize_comments_accepts_legacy_array_as_version_one() {
        let json = r#"
[
  {
    "id": "cmt_legacy",
    "anchor": {
      "blockType": "heading",
      "blockIndex": 3,
      "textHash": "sha256_prefix_8chars",
      "textSnippet": "JWT token",
      "charOffset": [12, 24]
    },
    "body": "Define refresh token expiry",
    "resolved": true,
    "createdAt": "2026-05-05T10:00:00Z",
    "updatedAt": "2026-05-05T10:00:01Z"
  }
]
"#;

        let comments =
            deserialize_for_file(SpecFileKey::Impl, json).expect("legacy array should deserialize");

        assert_eq!(
            vec![comment(
                "cmt_legacy",
                SpecFileKey::Impl,
                BlockType::Heading,
                true,
            )],
            comments.comments()
        );
    }

    #[test]
    fn deserialize_comments_defaults_missing_version_and_comments() {
        let comments = deserialize_for_file(SpecFileKey::Impl, "{}")
            .expect("missing wrapper fields should use defaults");

        assert!(comments.comments().is_empty());
    }

    #[test]
    fn deserialize_comments_defaults_missing_resolved_to_open() {
        let json = r#"
{
  "version": 1,
  "comments": [
    {
      "id": "cmt_default_open",
      "anchor": {
        "blockType": "paragraph",
        "blockIndex": 3,
        "textHash": "sha256_prefix_8chars",
        "textSnippet": "JWT token",
        "charOffset": [12, 24]
      },
      "body": "Define refresh token expiry",
      "createdAt": "2026-05-05T10:00:00Z",
      "updatedAt": "2026-05-05T10:00:01Z"
    }
  ]
}
"#;

        let comments = deserialize_for_file(SpecFileKey::Impl, json)
            .expect("missing resolved should default to open");

        assert_eq!(CommentStatus::Open, comments.comments()[0].status());
    }

    #[test]
    fn deserialize_comments_rejects_malformed_json() {
        let result = deserialize_for_file(SpecFileKey::Impl, "{");

        assert!(matches!(result, Err(CommentJsonError::MalformedJson(_))));
    }

    #[test]
    fn deserialize_comments_rejects_unsupported_version() {
        let result = deserialize_for_file(SpecFileKey::Impl, r#"{"version":2,"comments":[]}"#);

        assert!(matches!(
            result,
            Err(CommentJsonError::UnsupportedVersion { version: 2 })
        ));
    }

    #[test]
    fn deserialize_comments_rejects_unknown_block_type() {
        let json = r#"
{
  "version": 1,
  "comments": [
    {
      "id": "cmt_bad_block",
      "anchor": {
        "blockType": "image",
        "blockIndex": 3,
        "textHash": "sha256_prefix_8chars",
        "textSnippet": "JWT token",
        "charOffset": [12, 24]
      },
      "body": "Define refresh token expiry",
      "resolved": false,
      "createdAt": "2026-05-05T10:00:00Z",
      "updatedAt": "2026-05-05T10:00:01Z"
    }
  ]
}
"#;

        let result = deserialize_for_file(SpecFileKey::Impl, json);

        assert!(matches!(
            result,
            Err(CommentJsonError::UnsupportedBlockType { block_type })
                if block_type == "image"
        ));
    }

    #[test]
    fn deserialize_comments_rejects_invalid_domain_values() {
        let json = r#"
{
  "version": 1,
  "comments": [
    {
      "id": "cmt_bad_range",
      "anchor": {
        "blockType": "paragraph",
        "blockIndex": 3,
        "textHash": "sha256_prefix_8chars",
        "textSnippet": "JWT token",
        "charOffset": [24, 12]
      },
      "body": "Define refresh token expiry",
      "resolved": false,
      "createdAt": "2026-05-05T10:00:00Z",
      "updatedAt": "2026-05-05T10:00:01Z"
    }
  ]
}
"#;

        let result = deserialize_for_file(SpecFileKey::Impl, json);

        assert!(matches!(
            result,
            Err(CommentJsonError::Domain(
                CommentDomainError::InvalidCharRange { start: 24, end: 12 }
            ))
        ));
    }
}
